import { icon, avatar, logo } from './icons.js';
import { initialData, suggestions } from './data.js';
import { renderSecondary } from './secondary.js';
import { t, getLocale, setLocale, formatSchedule, formatRelative } from './i18n.js';
import { ensureEcosystemData, renderEcosystem, renderScenarios, renderAgentEcosystem, captureEcosystemWizard, rerenderEcosystemWizard, handleEcosystemAction } from './ecosystem.js';
import { ensureTeamData, renderTeam, renderHomeTeam, renderProjectWorkspace, handleTeamAction } from './team.js';
import { handleConnectionAction, handleConnectionChange, captureConnection, rerenderConnection, closeConnection } from './connection.js';
import { ensureChannelData, renderInbox, renderChannelHome, renderChannelTask, renderChannelTaskBadge, handleChannelAction, handleChannelChange, captureChannelDraft, rerenderChannelDraft, closeChannelDraft } from './channel.js';
import { recoverChannelRuns } from './channel-model.js';
import { createSpacesRoot, spaceBy, spaceName, normalizeSpace, switchSpace, SPACES_STORAGE_KEY } from './spaces-model.js';
import { handleSpacesAction, handleSpacesChange, renderSettings, renderSettingsSidebar, renderSpaceContext, renderSpaceMenu } from './spaces.js';
const tr = t;
const displayText = value => ['Personal','Team','Third-party','Squads','Auto','Slides','Deep Research','Data Visualization','Product Prototype','Office','Image','No description yet'].includes(value) ? tr(value) : formatRelative(value);
const agentDescription = a => a.description === 'No description yet' ? tr('No description yet') : a.description;
const suggestionText = index => tr('suggestion.'+index);

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let saved, savedSpaces;
try { saved = JSON.parse(localStorage.getItem('workmates-prototype-v1') || 'null'); savedSpaces = JSON.parse(localStorage.getItem(SPACES_STORAGE_KEY) || 'null'); } catch {}
const spaces = createSpacesRoot(savedSpaces,saved);
let data = spaceBy(spaces).data;
for(const space of spaces.spaces)recoverChannelRuns(space.data);
const workspaceDrafts = new Map();
const state = {page:'home',agent:'a1',task:null,project:null,detailTab:'Instructions',listTab:'tasks',filter:'all',query:'',libraryFilter:'all',hubFilter:'all',secondaryQuery:'',collapsed:false,mobileOpen:false,model:'Auto',selectedProject:'',capabilities:[],draft:'',attachment:'',recommendation:0,createAvatar:0,codeDraft:'',codeProject:'',settingsTab:'general',resourceTab:'projects',teamTab:'members',projectTab:'tasks',ecosystemWizard:null,connection:null,channelDraft:null};
let previousFocus, toastTimer, generationTimers=new Map();
const persist = () => { try { for(const space of spaces.spaces){space.name=space.data.enterprise.name;normalizeSpace(space);}localStorage.setItem(SPACES_STORAGE_KEY,JSON.stringify(spaces)); } catch { toast(tr('ui.storageUnavailable')); } };
const agentBy = id => data.agents.find(a=>a.id===id) || data.agents[0];
const taskBy = id => data.tasks.find(t=>t.id===id);
const button = (action,label,ic='',extra='',cls='btn') => `<button class="${cls}" data-action="${action}" ${extra}>${ic?icon(ic,16):''}${label}</button>`;
const iconButton=(action,name,label,extra='')=>{const match=extra.match(/class="([^"]*)"/);const classes=match?' '+match[1]:'';return `<button class="icon-btn${classes}" data-action="${action}" aria-label="${esc(label)}" title="${esc(label)}" ${extra.replace(/class="[^"]*"/,'')}>${icon(name,17)}</button>`;};
const menuItem=(action,label,name='',extra='',checked=false)=>`<button class="menu-item" data-action="${action}" ${extra}>${name?icon(name,16):''}<span>${esc(label)}</span>${checked?`<span class="menu-check">${icon('check',14)}</span>`:''}</button>`;
const workspaceContext = () => {
  const contextData=data;
  return {data:contextData,spaces,state,escape:esc,icon,avatar,t,modal,closeOverlay,persist,
    render:()=>{if(data===contextData)render();},navigate:(...args)=>{if(data===contextData)navigate(...args);},
    toast:message=>{if(data===contextData)toast(message);},button,switchWorkspace};
};
function switchWorkspace(id,{page='home',tab='general',notice=null}={}) {
  if(!spaceBy(spaces,id))return;
  const draftKeys=['draft','attachment','selectedProject','agent','model','capabilities','codeDraft','codeProject'];
  workspaceDrafts.set(data.tenantId,Object.fromEntries(draftKeys.map(key=>[key,structuredClone(state[key])])));
  closeOverlay();data=switchSpace(spaces,id);
  Object.assign(state,{page,agent:data.agents[0].id,task:null,project:null,selectedProject:'',draft:'',attachment:'',codeDraft:'',codeProject:'',model:'Auto',capabilities:[],query:'',secondaryQuery:'',filter:'all',listTab:'tasks',libraryFilter:'all',hubFilter:'all',detailTab:'Instructions',settingsTab:tab,resourceTab:'projects',teamTab:'members',projectTab:'tasks',channelFilter:'all',ecosystemWizard:null,connection:null,channelDraft:null,mobileOpen:false},workspaceDrafts.get(id)||{});
  persist();navigate(page,page==='team'?tab:undefined);toast(notice?tr(notice):tr('spaces.switched',{name:spaceName(spaceBy(spaces),tr('spaces.personal'))}));
}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('checkcircle',18)+`<span>${esc(message)}</span>`;$('#toast-root').replaceChildren(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200);}
function closeOverlay({preserveConnection=false,preserveChannel=false}={}){if(!preserveConnection)closeConnection(workspaceContext());if(!preserveChannel)closeChannelDraft(workspaceContext());document.querySelector('[data-action="language-menu"]')?.setAttribute('aria-expanded','false');const overlay=$('#overlay-root');overlay.innerHTML='';document.body.style.overflow='';if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
function modal(title,body,footer='',className=''){if(className!=='wx-connection-modal')closeConnection(workspaceContext());if(className!=='wx-channel-modal')closeChannelDraft(workspaceContext());previousFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop="true"><section class="modal ${className}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2>${iconButton('close','close',tr('Close'))}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay-root input, #overlay-root textarea, #overlay-root button')?.focus(),30);}
function popover(el,content){closeConnection(workspaceContext());closeChannelDraft(workspaceContext());previousFocus=el;const rect=el.getBoundingClientRect();$('#overlay-root').innerHTML=`<div class="popover-backdrop" data-action="close"></div><div class="popover" role="menu">${content}</div>`;const p=$('.popover');p.style.left=Math.max(8,Math.min(rect.left,innerWidth-p.offsetWidth-12))+'px';p.style.top=(rect.bottom+p.offsetHeight+8>innerHeight?Math.max(8,rect.top-p.offsetHeight-6):rect.bottom+6)+'px';p.querySelector('button')?.focus();}
function navigate(page,id){closeOverlay();state.page=page;state.query='';state.filter='all';state.listTab='tasks';state.mobileOpen=false;if(['team','settings'].includes(page))state.settingsTab=id||'general';if(page==='detail'){state.agent=id||state.agent;state.detailTab='Instructions';}if(page==='task'){state.task=id;const t=taskBy(id);if(t){t.unread=false;state.agent=t.agent;persist();}}if(page==='project'){state.project=id;state.projectTab='tasks';}if(page==='new'&&id)state.agent=id;const hash=page+(id?'/'+id:'');if(location.hash.slice(1)!==hash)history.pushState({},'',`#${hash}`);render();window.scrollTo(0,0);}
function readRoute(){const [page,id]=location.hash.slice(1).split('/');if(['home','new','detail','task','automations','projects','project','library','hub','code','ecosystem','scenarios','team','settings','inbox'].includes(page)){state.page=page;if(['team','settings'].includes(page))state.settingsTab=id||'general';if(page==='detail'||page==='new')state.agent=id||'a1';if(page==='task'){state.task=id;if(!taskBy(id))state.page='home';else state.agent=taskBy(id).agent;}if(page==='project'){state.project=id;if(!data.projects.some(p=>p.id===id))state.page='projects';}}render();}
function sidebar() {
  const groups=[['workspace.work',[['home','home','Home'],['inbox','chat','workspace.inbox'],['new','edit','New Task'],['projects','folder','workspace.projects'],['library','library','Library']]],['workspace.resources',[['hub','hub','Hub'],['scenarios','grid','workspace.scenarios'],['automations','bolt','Automations']]],['workspace.manage',[['team','users',data.spaceType==='organization'?'spaces.manage':'spaces.workspaceSettings'],['ecosystem','globe','workspace.ecosystem']]]];
  return `<aside class="sidebar" ${state.collapsed||innerWidth<=680&&!state.mobileOpen?'inert':''}>
    <div class="brand"><button class="brand-logo" data-action="nav" data-page="home" aria-label="${tr('WorkX home')}">${logo()}</button><div class="brand-word">WorkX</div><div class="brand-actions">${iconButton('global-search','search',tr('Search · ⌘K'))}${iconButton('collapse','collapse',tr('Collapse sidebar'))}</div></div>
    <div class="mode-switch" role="tablist" aria-label="${tr('Workspace mode')}"><button role="tab" aria-selected="${state.page!=='code'}" class="${state.page!=='code'?'active':''}" data-action="nav" data-page="home">${icon('grid',12)}${tr('Work')}</button><button role="tab" aria-selected="${state.page==='code'}" class="${state.page==='code'?'active':''}" data-action="nav" data-page="code">${icon('code',13)}${tr('Code')}</button></div>
    <nav class="main-nav" aria-label="${tr('Main navigation')}">${groups.map(([group,items])=>`<div class="nav-group-label">${tr(group)}</div>${items.map(([page,ic,label])=>{const selected=state.page===page||page==='projects'&&state.page==='project';return `<a href="#${page}" class="nav-item ${selected?'active':''}" data-action="nav" data-page="${page}" ${selected?'aria-current="page"':''}>${icon(ic,17)}<span>${tr(label)}</span>${page==='scenarios'?`<small class="nav-reserved">${tr('workspace.reserved')}</small>`:''}</a>`;}).join('')}`).join('')}</nav>
    <section class="sidebar-tasks"><div class="sidebar-label"><button data-action="nav" data-page="home">${tr('Tasks')}</button>${iconButton('sidebar-settings','settings',tr('Task list settings'))}</div>${data.tasks.filter(task=>!task.archived).sort((a,b)=>(!!b.pinned)-(!!a.pinned)).slice(0,16).map(task=>`<div class="sidebar-task ${state.page==='task'&&state.task===task.id?'current':''}"><button class="task-title" title="${esc(task.name)}" data-action="open-task" data-id="${task.id}">${task.pinned?icon('star',12)+' ':''}${esc(task.name)}</button>${task.unread?'<span class="dot"></span>':''}${iconButton('task-menu','more',tr('ui.moreTask',{name:task.name}),`data-id="${task.id}"`)}</div>`).join('')}</section>
    <div class="sidebar-language"><button class="language-trigger" data-action="language-menu" aria-label="${tr('language.choose')}" aria-haspopup="menu" aria-expanded="false">${icon('globe',16)}<span>${getLocale()==='en'?'English':'中文'}</span><small>${tr('language.label')}</small>${icon('chevron',11)}</button></div>
    <div class="sidebar-footer"><button class="profile-btn" data-action="profile"><span class="profile-avatar">${esc(spaces.user.name.slice(0,1).toUpperCase())}</span><span class="ws-profile-copy"><strong>${esc(spaceName(spaceBy(spaces),tr('spaces.personal')))}</strong><small>${tr('spaces.'+data.spaceType)}</small></span>${icon('chevron',11)}</button>${iconButton('proactive','moon',tr('Proactive help'))}<button class="icon-btn notice-btn" data-action="notifications" aria-label="${tr('Notifications')}">${icon('bell',18)}${!data.notificationsRead?'<span class="notice-badge">1</span>':''}</button></div>
  </aside>`;
}
function render() {
  const isChannelTask=state.page==='task'&&taskBy(state.task)?.kind==='channel';
  const channelScroll=isChannelTask&&$('.chat-scroll')?.dataset?.channelTask===state.task?$('.chat-scroll').scrollTop:0;
  ensureTeamData(data);
  for(const p of data.projects)p.tasks=data.tasks.filter(task=>task.project===p.id&&!task.archived).length;
  const secondary=['automations','projects','library','hub','code'];
  const workspacePages={ecosystem:renderEcosystem,scenarios:renderScenarios,team:renderSettings,settings:renderSettings,inbox:renderInbox};
  let content=state.page==='home'?home():state.page==='new'?newTask():state.page==='detail'?details():state.page==='task'?chat():state.page==='project'?projectPage():workspacePages[state.page]?workspacePages[state.page](workspaceContext()):secondary.includes(state.page)?renderSecondary(state.page,{...data,agents:data.agents.map(a=>({...a,description:agentDescription(a)})),icon,avatar,escape:esc,query:state.secondaryQuery,libraryFilter:state.libraryFilter,hubFilter:state.hubFilter,codeDraft:state.codeDraft,codeProject:state.codeProject}):home();
  const settingsPage=['team','settings'].includes(state.page);
  $('#app').innerHTML=`<div class="app-layout ${settingsPage?'ws-settings-layout':''} ${state.collapsed?'collapsed':''} ${state.mobileOpen?'mobile-open':''}"><div class="mobile-scrim" data-action="collapse"></div>${settingsPage?renderSettingsSidebar(workspaceContext()):sidebar()}<button class="icon-btn floating-expand" data-action="expand" aria-label="${tr('Expand sidebar')}">${icon('collapse',18)}</button><main class="main" id="main-content">${settingsPage?'':renderSpaceContext(workspaceContext())}${content}</main></div>`;
  const title=state.page==='detail'?agentBy(state.agent).name:state.page==='task'?taskBy(state.task)?.name:tr({home:'Home',new:'New Task',automations:'Automations',projects:'Projects',library:'Library',hub:'Hub',code:'Code',project:'Project',ecosystem:'workspace.ecosystem',scenarios:'workspace.scenarios',team:data.spaceType==='organization'?'spaces.manage':'spaces.workspaceSettings',settings:'spaces.settings',inbox:'workspace.inbox'}[state.page]||'Home');
  document.title=`${title} · WorkX`;
  document.documentElement.lang=getLocale();
  document.querySelector('meta[name="description"]').content=tr('ui.description');
  if(isChannelTask){const scroll=$('.chat-scroll');if(scroll)scroll.scrollTop=channelScroll;}
  else if(state.page==='task')setTimeout(()=>{const scroll=$('.chat-scroll');if(scroll)scroll.scrollTop=scroll.scrollHeight;},0);
}
function agentCard(a) {
  return `<article class="agent-card" tabindex="0" role="button" aria-label="${esc(tr('ui.viewAgent',{name:a.name}))}" data-action="agent-detail" data-id="${a.id}"><div class="agent-card-top">${avatar(a.avatar,36)}<span class="agent-card-name" title="${esc(a.name)}">${esc(a.name)}</span><button class="chat-button" data-action="chat-agent" data-id="${a.id}" aria-label="${esc(tr('ui.chatAgent',{name:a.name}))}">${icon('chat',16)}</button></div><div class="agent-desc">${esc(agentDescription(a))}</div><div class="agent-meta"><span>${icon('chat',12)}${a.tasks}</span><span>${icon(a.tag==='Squads'?'users':'layers',12)}${a.skills}</span>${a.tag?`<span class="tag">${esc(displayText(a.tag))}</span>`:''}</div></article>`;
}
function workspaceEntries() {
  return `<div class="workspace-entry-strip"><button class="workspace-entry" data-action="nav" data-page="ecosystem">${icon('globe',23)}<div class="workspace-entry-copy"><strong>${tr('workspace.ecosystem')} · ${tr('workspace.ecosystemIntro')}</strong><p>${tr('workspace.ecosystemPlatforms')}</p></div>${icon('chevron',14)}</button><button class="workspace-entry" data-action="nav" data-page="scenarios">${icon('grid',23)}<div class="workspace-entry-copy"><strong>${tr('workspace.scenarios')} · ${tr('workspace.scenarioIntro')}</strong><p>${tr('workspace.scenarioStatus')}</p></div>${icon('chevron',14)}</button></div>`;
}
function projectHint() {
  const project=data.projects.find(p=>p.id===state.selectedProject);
  return project?`<div class="workspace-project-hint">${icon('users',18)}<div class="grow"><strong>${esc(project.name)}</strong><p>${tr('workspace.projectContext')}</p></div><button class="text-btn" data-action="open-project" data-id="${esc(project.id)}">${tr('workspace.projectLink')}${icon('chevron',12)}</button></div>`:'';
}
function taskCollaboration(task) {
  const project=data.projects.find(p=>p.id===task.project);
  if(!project)return '';
  const owner=data.teamMembers.find(m=>m.id===task.ownerId);
  const agentCount=new Set([task.agent,...(task.supportingAgentIds||[])]).size;
  const review=task.status==='running'?'workspace.running':task.reviewState==='accepted'?'workspace.accepted':'workspace.review';
  return `<div class="workspace-task-team" aria-label="${tr('workspace.taskTeam')}"><button class="team-project" data-action="open-project" data-id="${esc(project.id)}">${icon('folder',15)}<span class="ellipsis">${esc(project.name)}</span>${icon('chevron',11)}</button><span class="task-owner">${esc(owner?tr('workspace.owner',{name:owner.name}):tr('workspace.unassigned'))}</span><span class="muted">${tr('workspace.agents',{count:agentCount})}</span><button class="text-btn" data-action="team-assign-task" data-id="${esc(task.id)}">${tr('workspace.assign')}</button>${task.kind==='channel'?renderChannelTaskBadge(task,workspaceContext()):`<span class="task-review ${task.reviewState==='accepted'?'is-accepted':''}">${tr(review)}</span>`}</div>`;
}
function home() {
  return `<div class="home-page">${renderHomeTeam(workspaceContext())}${workspaceEntries()}${renderChannelHome(workspaceContext())}<section><div class="section-heading"><h2>${tr('Workmates and squads')}</h2><div class="heading-actions"><button class="text-btn" data-action="create-menu">${icon('plus',14)}${tr('Create')}</button><span class="divider"></span><button class="text-btn" data-action="nav" data-page="hub">${tr('All')} ${icon('chevron',11)}</button></div></div><div class="agents-grid">${data.agents.map(agentCard).join('')}</div></section>${!data.hideQuick?`<section class="quick-section"><div class="section-heading"><h2>${tr('Quick start')}</h2><button class="text-btn" data-action="hide-quick">${tr("Don't Show Again")}</button></div><div class="quick-grid"><div class="quick-card quick-add"><h3>${tr('Add more Workmates')}</h3><p>${tr('Find skilled Workmates ready to work for you.')}</p><button class="quick-action" data-action="nav" data-page="hub">${icon('grid',15)}${tr('Browse Workmates')}</button><button class="quick-action" data-action="create-agent">${icon('users',17)}${tr('Create a Workmate')}</button></div><div class="quick-card"><div class="quick-card-head"><h3>${tr('Kick off a task')}</h3>${iconButton('refresh-recommendations','refresh',tr('Refresh recommendations'))}</div>${[0,1,2].map(n=>{const idx=(n+state.recommendation)%suggestions.length,s=suggestions[idx];return `<button class="recommendation" data-action="suggestion" data-index="${idx}">${avatar(agentBy(s.agent).avatar,20)}<span>${esc(suggestionText(idx))}</span>${icon('arrow',15)}</button>`;}).join('')}</div></div></section>`:''}${taskSection()}</div>`;
}
function taskSection() {
  return `<section class="task-section"><div class="list-toolbar"><div class="tabs" role="tablist" aria-label="${tr('Recent activity')}">${['tasks','automations',...(state.page==='new'?['artifacts']:[])].map(tab=>`<button class="tab-btn ${state.listTab===tab?'active':''}" role="tab" aria-selected="${state.listTab===tab}" data-action="list-tab" data-tab="${tab}">${tr(tab[0].toUpperCase()+tab.slice(1))}</button>`).join('')}</div><div class="list-tools">${iconButton('filter','filter',tr('Filter tasks'),`class="filter-btn ${state.filter!=='all'?'selected':''}"`)}<label class="search-field">${icon('search',16)}<input data-task-search value="${esc(state.query)}" placeholder="${tr('Search')}" aria-label="${tr('Search tasks')}"></label></div></div><div id="task-results">${taskRows()}</div></section>`;
}
function taskRows() {
  if(state.listTab==='automations')return data.automations.filter(a=>a.name.toLowerCase().includes(state.query.toLowerCase())).map(a=>`<div class="task-row"><button class="task-open" data-action="nav" data-page="automations">${icon('clock',20)}<span>${esc(a.name)}</span></button><span class="task-date">${tr(a.enabled?'Active':'Paused')} · ${esc(formatSchedule(a.schedule))}</span></div>`).join('')||empty(tr('No automations found'),tr('试试其他关键词'));
  if(state.listTab==='artifacts')return data.library.filter(f=>f.name.toLowerCase().includes(state.query.toLowerCase())).map(f=>`<div class="task-row"><button class="task-open" data-action="open-file" data-id="${f.id}">${icon('file',20)}${esc(f.name)}</button><span class="task-date">${esc(formatRelative(f.updated))}</span></div>`).join('')||empty(tr('No files found'),tr('试试其他关键词'));
  const tasks=data.tasks.filter(task=>(state.filter==='archived'?task.archived:!task.archived)&&task.name.toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='all'||state.filter==='archived'||state.filter==='unread'&&task.unread||state.filter==='pinned'&&task.pinned||state.filter==='done'&&task.status==='done')).sort((a,b)=>(!!b.pinned)-(!!a.pinned));
  return tasks.length?tasks.map(task=>`<div class="task-row"><button class="task-open" data-action="open-task" data-id="${task.id}">${state.page==='home'?avatar(agentBy(task.agent).avatar,24):''}<span class="ellipsis">${esc(task.name)}${task.unread?'<span class="dot"></span>':''}</span></button>${task.kind==='channel'?renderChannelTaskBadge(task,workspaceContext()):''}<span class="task-date">${esc(task.date)}</span><button class="icon-btn task-more" aria-label="${esc(tr('ui.moreTask',{name:task.name}))}" data-action="task-menu" data-id="${task.id}">${icon('more',17)}</button></div>`).join(''):empty(tr('No tasks found'),tr('试试其他关键词，或创建一个新任务。'));
}
function empty(title,description){return `<div class="empty-state">${icon('search',25)}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;}
function composer(followup=false) {
  return `<div class="composer">${state.attachment?`<div class="attachment-pill">${icon('file',14)}${esc(state.attachment)}${iconButton('remove-attachment','close',tr('Remove attachment'))}</div>`:''}<textarea id="task-prompt" aria-label="${tr('Task or goal')}" placeholder="${esc(tr(followup?'Ask a follow-up…':"What's your task or goal?"))}" rows="2">${esc(state.draft)}</textarea><div class="composer-bottom">${iconButton('attach-menu','plus',tr('Add attachment'))}<span class="separator"></span><button class="chip-btn" data-action="select-project">${icon('folder',15)}<span>${esc(data.projects.find(p=>p.id===state.selectedProject)?.name||tr('Select project'))}</span>${icon('chevron',10)}</button>${['Slides','Deep Research'].map((c,n)=>`<button class="chip-btn capability-chip ${state.capabilities.includes(c)?'active':''}" data-action="capability" data-value="${c}">${icon(n?'globe':'file',15)}${tr(c)}</button>`).join('')}<button class="chip-btn more-cap" data-action="more-capabilities">${icon('grid',15)}${tr('More')}</button><button class="chip-btn model" data-action="select-model">${esc(displayText(state.model))}${icon('chevron',10)}</button>${iconButton('voice','mic',tr('Voice input'),'class="mic-control"')}<button class="send-btn" data-action="send-task" aria-label="${tr('Send task')}" ${!state.draft.trim()?'disabled':''}>${icon('arrow',23)}</button></div></div>`;
}
function newTask() {
  const a=agentBy(state.agent);
  return `<div class="new-page"><div class="new-hero"><div class="agent-greeting">${avatar(a.avatar,56)}<button class="greeting-name" data-action="select-agent">${esc(a.name)}<span style="transform:rotate(90deg);display:inline-flex">${icon('chevron',13)}</span></button><button class="text-btn details-link" data-action="agent-detail" data-id="${a.id}">${tr('Workmate Details')} ${icon('chevron',12)}</button></div>${composer()}${projectHint()}</div><section class="for-you"><div class="for-you-title"><h2>${tr('For You')}</h2><p>${tr('Here are a few recommended tasks based on your recent activity:')}</p></div><div class="suggestion-grid">${[3,4,0].map(index=>{const s=suggestions[index];return `<button class="suggestion-card" data-action="fill-suggestion" data-index="${index}"><span class="suggestion-label">${icon(s.icon,13)}${tr(s.label)}</span><p>${esc(suggestionText(index))}</p></button>`;}).join('')}</div></section>${taskSection()}</div>`;
}
function details() {
  const a=agentBy(state.agent),tabs=['Instructions','Capabilities','Work Context','Ecosystem','Manage'];let body='';
  if(state.detailTab==='Instructions')body=`<div class="detail-label"><h2>${tr('Instructions')}</h2>${button('edit-instructions',tr('Edit'),'edit')}</div><div class="instruction-box">${esc(a.instructions||tr('ui.defaultInstructions'))}</div>`;
  if(state.detailTab==='Capabilities') {
    const builtins=[['file','文档与写作','整理资料、提炼观点，生成专业文档。'],['globe','深度调研','梳理问题，形成完整的研究框架。'],['code','代码与开发','理解代码，协助开发与故障排查。'],['grid','数据分析','清理数据，探索趋势与关键洞察。'],['play','演示文稿','将想法整理成清晰的汇报材料。'],['users','团队协作','拆解任务，协调伙伴与工作进度。']].map(([ic,title,desc])=>[ic,tr(title),tr(desc)]);
    const items=[...builtins,...(a.extraSkills||[]).map(s=>['layers',s,tr('已添加到当前伙伴的演示能力。')])];
    body=`<div class="detail-label"><h2>${tr('Skills & tools')}</h2>${button('add-capability',tr('Add capability'),'plus')}</div><div class="capability-grid">${items.map(([ic,title,desc])=>`<div class="capability-item">${icon(ic,22)}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`).join('')}</div>`;
  }
  if(state.detailTab==='Work Context')body=`<div class="detail-label"><h2>${tr('Work context')}</h2>${button('add-context',tr('Add context'),'plus')}</div><p class="muted">${tr('给伙伴一些工作背景，让每次协作更有默契。')}</p><div class="instruction-box">${esc(a.context||tr('ui.defaultContext'))}</div>`;
  if(state.detailTab==='Ecosystem')body=renderAgentEcosystem(a.id,workspaceContext());
  if(state.detailTab==='Manage')body=`<h2>${tr('Workmate settings')}</h2><div class="instruction-box"><div class="detail-label"><div>${tr('Basic information')}<p class="muted" style="font-size:12px;margin:4px 0">${tr('名称、介绍与伙伴头像')}</p></div>${button('edit-agent',tr('Edit'),'edit',`data-id="${a.id}"`)}</div><div class="detail-label"><div>${tr('Display on Home')}<p class="muted" style="font-size:12px;margin:4px 0">${tr('当前伙伴已添加至你的工作台')}</p></div>${icon('checkcircle',20)}</div></div>`;
  return `<div class="detail-page"><div class="breadcrumbs"><button data-action="nav" data-page="home">${tr('Home')}</button>${icon('chevron',12)}<button data-action="chat-agent" data-id="${a.id}">${esc(a.name)}</button>${icon('chevron',12)}<span>${tr('Details')}</span>${iconButton('agent-menu','more',tr('More workmate actions'),`data-id="${a.id}" style="margin-left:auto"`)}</div><section class="agent-profile">${avatar(a.avatar,64)}<div class="grow"><div class="row"><h1>${esc(a.name)}</h1>${a.tag?`<span class="tag">${esc(displayText(a.tag))}</span>`:''}${iconButton('edit-agent','edit',tr('Edit basic info'),`data-id="${a.id}"`)}</div><p>${esc(agentDescription(a))}</p><div class="profile-controls"><button class="soft-chip" data-action="select-model">${icon('star',12)}${esc(displayText(state.model))}${icon('chevron',10)}</button><button class="soft-chip" data-action="proactive">${icon('moon',12)}${tr(data.proactive?'ui.proactiveOn':'ui.proactiveOff')} ${icon('chevron',10)}</button></div></div><div class="profile-cta">${button('nav',tr('workspace.ecosystem'),'globe','data-page="ecosystem"')}${button('chat-agent',tr('New Task'),'edit',`data-id="${a.id}"`)}</div></section><div class="detail-tabs"><div class="tabs underlined" role="tablist">${tabs.map(tab=>`<button class="tab-btn ${state.detailTab===tab?'active':''}" role="tab" aria-selected="${state.detailTab===tab}" data-action="detail-tab" data-tab="${tab}">${tr(tab==='Ecosystem'?'workspace.ecosystem':tab)}</button>`).join('')}</div></div><div class="detail-body">${body}</div></div>`;
}
function answerMarkup(task) {
  if(task.status==='running')return `<div class="progress-line"><span class="pulse"></span>${tr('chat.running')}</div><p>${tr('chat.runningDescription')}</p>`;
  const isCode=task.kind==='code',isResearch=/调研|研究|Research/.test(task.name);
  return `<div class="progress-line">${icon('checkcircle',14)}${tr('chat.completed')} <span class="demo-badge">${tr('chat.demo')}</span></div><p>${esc(tr('chat.received',{prompt:task.prompt||task.name}))}</p><p>${tr('chat.intro')}</p><h3>${tr(isCode?'chat.planCode':isResearch?'chat.planResearch':'chat.plan')}</h3><ol><li><strong>${tr('chat.scope')}</strong> — ${tr('chat.scopeBody')}</li><li><strong>${tr(isCode?'chat.organizeCode':'chat.organize')}</strong> — ${tr(isCode?'chat.organizeCodeBody':'chat.organizeBody')}</li><li><strong>${tr('chat.execute')}</strong> — ${tr('chat.executeBody')}</li></ol><h3>${tr('chat.next')}</h3><p>${tr('chat.nextBody')}</p><button class="answer-artifact" data-action="open-file" data-id="${esc(task.file||'f1')}"><span class="artifact-icon">${icon('file',22)}</span><span class="grow"><strong>${esc(tr('chat.deliverable',{name:task.name}))}</strong><br><small>${tr('Document · Click to preview')}</small></span>${icon('chevron',16)}</button><div class="row">${iconButton('copy-answer','copy',tr('Copy answer'),`data-id="${task.id}"`)}${button('followup-suggestion',tr('整理为行动清单'),'','','soft-chip')}</div>`;
}
function chat() {
  const task=taskBy(state.task);if(!task)return home();const a=agentBy(task.agent);
  if(task.kind==='channel')return `<div class="chat-page"><header class="chat-header">${data.agents.some(agent=>agent.id===task.agent)?avatar(a.avatar,29):icon('robot',29)}<h1 title="${esc(task.name)}">${esc(task.name)}</h1>${iconButton('task-menu','more',tr('Task actions'),`data-id="${task.id}"`)}${button('nav',tr('workspace.inbox'),'chat','data-page="inbox"')}</header>${taskCollaboration(task)}<div class="chat-scroll" data-channel-task="${esc(task.id)}">${renderChannelTask(task,workspaceContext())}</div></div>`;
  return `<div class="chat-page"><header class="chat-header">${avatar(a.avatar,29)}<h1 title="${esc(task.name)}">${esc(task.name)}</h1>${iconButton('task-menu','more',tr('Task actions'),`data-id="${task.id}"`)}${iconButton('agent-detail','settings',tr('Workmate details'),`data-id="${a.id}"`)}</header>${taskCollaboration(task)}<div class="chat-scroll"><div class="chat-user">${esc(task.prompt||task.name)}${task.attachment?`<div class="attachment-pill" style="margin:10px 0 0;background:white">${icon('file',14)}${esc(task.attachment)}</div>`:''}${task.capabilities?.length?`<div class="prototype-note" style="margin-top:8px">${esc(task.capabilities.map(displayText).join(' · '))} · ${esc(displayText(task.model||'Auto'))}</div>`:''}</div><div class="assistant-header">${avatar(a.avatar,29)}${esc(a.name)}<span class="demo-badge">${tr('Prototype')}</span></div><div class="assistant-answer">${answerMarkup(task)}</div>${(task.replies||[]).map(r=>`<div class="chat-user" style="margin-top:28px">${esc(r.prompt)}</div><div class="assistant-header">${avatar(a.avatar,29)}${esc(a.name)}</div><div class="assistant-answer"><p>${esc(tr('chat.followup',{prompt:r.prompt}))}</p><ol><li>${tr('chat.prepare')}</li><li>${tr('chat.work')}</li><li>${tr('chat.deliver')}</li></ol><p class="prototype-note">${tr('chat.preset')}</p></div>`).join('')}</div><div class="chat-composer">${composer(true)}<div class="chat-footnote">${tr('chat.footnote')}</div></div></div>`;
}
function projectPage() {
  const project=data.projects.find(p=>p.id===state.project);
  return project?renderProjectWorkspace(project,workspaceContext()):renderSecondary('projects',{...data,icon,avatar,escape:esc});
}

function actionText(key, params) { return t(key, params); }

function showSearch(query=''){previousFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay" data-backdrop="true"><section class="modal search-modal" role="dialog" aria-modal="true" aria-label="${esc(actionText("Search everything"))}"><div class="global-search-box">${icon('search',22)}<input id="global-search" placeholder="${esc(actionText("Search tasks, workmates, and projects…"))}" aria-label="${esc(actionText("Search everything"))}" value="${esc(query)}" autocomplete="off"><button class="kbd" data-action="close">Esc</button></div><div id="global-results" class="search-results">${searchResults(query)}</div><div class="modal-footer" style="justify-content:space-between;font-size:11px;color:#9ca1a8;padding:10px 20px"><span>${esc(actionText("Find something to pick up where you left off"))}</span><span>⌘ K</span></div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#global-search')?.focus(),20);}
function searchResults(query){const q=query.trim().toLowerCase(),groups=[[actionText('Workmates'),data.agents.filter(a=>(a.name+' '+a.description).toLowerCase().includes(q)).slice(0,4),a=>`<button class="search-result" data-action="agent-detail" data-id="${a.id}">${avatar(a.avatar,26)}<span>${esc(a.name)}</span>${icon('chevron',13)}</button>`],[actionText('Tasks'),data.tasks.filter(t=>!t.archived&&t.name.toLowerCase().includes(q)).slice(0,6),t=>`<button class="search-result" data-action="open-task" data-id="${t.id}">${icon('chat',19)}<span>${esc(t.name)}</span>${icon('chevron',13)}</button>`],[actionText('Projects'),data.projects.filter(p=>p.name.toLowerCase().includes(q)).slice(0,3),p=>`<button class="search-result" data-action="open-project" data-id="${p.id}">${icon('folder',19)}<span>${esc(p.name)}</span>${icon('chevron',13)}</button>`]];return groups.filter(([,items])=>items.length).map(([name,items,renderer])=>`<div class="search-caption">${name}</div>${items.map(renderer).join('')}`).join('')||empty(actionText('No results found'),actionText('换一个关键词试试'));}
function createAgent(editId,squad=false){const a=editId?agentBy(editId):null;state.createAvatar=a?.avatar??(squad?5:0);modal(a?actionText('Edit workmate'):squad?actionText('Create a squad'):actionText('Create a Workmate'),`<form id="agent-form" data-edit="${a?.id||''}"><div class="avatar-options">${[0,1,2,3,4,5].map(i=>`<button type="button" class="avatar-option ${i===state.createAvatar?'selected':''}" data-action="pick-avatar" data-value="${i}" aria-label="${esc(actionText('actions.avatar',{number:i+1}))}" aria-pressed="${i===state.createAvatar}">${avatar(i,42)}</button>`).join('')}</div><label class="form-field"><span>${esc(actionText("Name"))} <span class="muted">*</span></span><input name="name" placeholder="${esc(actionText("Give your workmate a name"))}" value="${esc(a?.name||'')}" maxlength="40" required></label><label class="form-field"><span>${esc(actionText("Description"))}</span><textarea name="description" placeholder="${esc(actionText("What can this workmate help you with?"))}" maxlength="300">${esc(a?.description==='No description yet'?'':a?.description||'')}</textarea></label><label class="form-field"><span>${esc(actionText("Type"))}</span><select name="tag">${['Personal','Team','Third-party','Squads'].map(tag=>`<option value="${tag}" ${tag===(a?.tag||(squad?'Squads':'Personal'))?'selected':''}>${esc(actionText(tag))}</option>`).join('')}</select></label><p class="prototype-note">${esc(actionText("保存在此浏览器中，随时可以编辑。"))}</p></form>`,button('close',actionText('Cancel'))+button('save-agent',a?actionText('Save changes'):actionText('Create Workmate'),'','','btn primary'));setTimeout(()=>$('#agent-form input')?.focus(),40);}
function createAutomation(){modal(actionText('New automation'),`<form id="automation-form"><label class="form-field"><span>${esc(actionText("Name"))} <span class="muted">*</span></span><input name="name" placeholder="${esc(actionText("e.g. 每周工作报告"))}" maxlength="60" required></label><label class="form-field"><span>${esc(actionText("Task instructions"))} <span class="muted">*</span></span><textarea name="description" placeholder="${esc(actionText("Describe what your workmate should do…"))}" required></textarea></label><label class="form-field"><span>${esc(actionText("Schedule"))}</span><select name="frequency"><option value="Every weekday">${esc(actionText("Every weekday"))}</option><option value="Every day">${esc(actionText("Every day"))}</option><option value="Every Monday">${esc(actionText("Every Monday"))}</option><option value="Every Friday">${esc(actionText("Every Friday"))}</option></select></label><label class="form-field"><span>${esc(actionText("Time"))}</span><input type="time" name="time" value="09:00" required></label><p class="prototype-note">${esc(actionText("原型仅演示自动化配置与状态切换，不会真正定时执行。"))}</p></form>`,button('close',actionText('Cancel'))+button('save-automation',actionText('Create automation'),'','','btn primary'));}
function createProject(){modal(actionText('New project'),`<form id="project-form"><label class="form-field"><span>${esc(actionText("Project name"))} <span class="muted">*</span></span><input name="name" placeholder="${esc(actionText("What are you working on?"))}" required maxlength="60"></label><label class="form-field"><span>${esc(actionText("Description"))}</span><textarea name="description" placeholder="${esc(actionText("A little context goes a long way…"))}"></textarea></label></form>`,button('close',actionText('Cancel'))+button('save-project',actionText('Create project'),'','','btn primary'));}
function showFile(id){const f=data.library.find(f=>f.id===id)||data.library[0];const body=f.content||actionText('actions.defaultDocument');modal(f.name,`<div class="row" style="margin-bottom:17px;color:#8f959e;font-size:12px">${icon('file',15)}${{doc:actionText('Document'),slides:actionText('Presentation preview'),sheet:actionText('Spreadsheet preview')}[f.type]} · ${esc(displayText(f.updated))}<span class="demo-badge">${esc(actionText("Demo content"))}</span></div><div class="file-preview"><h2>${esc(f.name)}</h2>${esc(body)}</div>`,button('close',actionText('Close'))+button('download-file',actionText('Download .md'),'download',`data-id="${f.id}"`,'btn primary'));}
function notifications(){
  previousFocus=document.activeElement;data.notificationsRead=true;persist();render();
  const completed=data.tasks.find(task=>task.status==='done'&&task.unread)||data.tasks.find(task=>task.status==='done');
  const taskNotice=completed?`<button class="notice-item" data-action="open-task" data-id="${esc(completed.id)}" style="text-align:left;width:100%"><span class="notification-icon">${icon('checkcircle',20)}</span><span><strong>${esc(actionText('你的智能伙伴已完成任务'))}</strong><p>${esc(actionText('actions.notificationComplete',{name:completed.name}))}</p></span></button>`:'';
  $('#overlay-root').innerHTML=`<div class="overlay drawer-overlay" data-backdrop="true"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(actionText('Notifications'))}"><div class="modal-header"><h2>${esc(actionText('Notifications'))}</h2>${iconButton('close','close',actionText('Close notifications'))}</div><div class="modal-body"><p class="muted" style="font-size:12px">${esc(spaceName(spaceBy(spaces),tr('spaces.personal')))} · ${tr('spaces.contextHint')}</p>${taskNotice}<div class="notice-item"><span class="notification-icon" style="color:#6c82c9;background:#f0f3fc">${icon('users',20)}</span><div><strong>${esc(actionText('欢迎来到你的 WorkX 工作台'))}</strong><p>${esc(actionText('选择一个智能伙伴，开始你的第一个任务。'))}</p><small>${esc(actionText('Getting started'))}</small></div></div></div></aside></div>`;document.body.style.overflow='hidden';
}
function startTask(prompt,kind='work') {
  const text=prompt.trim();if(!text)return;
  const taskData=data,tenantId=taskData.tenantId,id='t'+Date.now()+Math.random().toString(36).slice(2,6),fileId='f'+id;
  const currentAgent=agentBy(kind==='code'?'a3':state.agent);
  const date=new Date().toLocaleString('en-US',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).replace(',','');
  const task={id,tenantId,ownerId:'m1',name:text.length>30?text.slice(0,30)+'…':text,prompt:text,date,agent:currentAgent.id,status:'running',project:state.selectedProject,file:fileId,kind,attachment:state.attachment,model:state.model,capabilities:[...state.capabilities]};
  taskData.tasks.unshift(task);currentAgent.tasks++;
  taskData.library.unshift({id:fileId,tenantId,ownerId:'m1',project:state.selectedProject,name:text.slice(0,24)+' · '+actionText('actions.deliverable'),type:'doc',updated:'Just now',content:actionText('actions.generatedDocument',{prompt:text})});
  const project=taskData.projects.find(p=>p.id===state.selectedProject);
  if(project){project.tasks=(project.tasks||0)+1;if(!project.agentIds.includes(currentAgent.id))project.agentIds.push(currentAgent.id);}
  state.draft='';state.attachment='';if(kind==='code'){state.codeDraft='';state.codeProject='';}
  persist();navigate('task',id);
  const timer=setTimeout(()=>{
    const task=taskData.tasks.find(t=>t.id===id);
    if(task){task.status='done';task.unread=data!==taskData||state.task!==id||state.page!=='task';persist();if(data===taskData){if(['task','project','team','home'].includes(state.page))render();if(spaces.user.notifications&&(state.page!=='task'||state.task!==id))toast(actionText('智能伙伴已完成演示任务'));}}
    generationTimers.delete(tenantId+':'+id);
  },1600);
  generationTimers.set(tenantId+':'+id,timer);
}
function downloadFile(id){const f=data.library.find(f=>f.id===id);if(!f)return;const content=`# ${f.name}\n\n${f.content||actionText('actions.downloadDefault')}\n\n---\n${actionText('actions.downloadFooter')}`;const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=f.name+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(actionText('文档已下载'));}

async function action(el,event){const a=el.dataset.action,id=el.dataset.id;
if(handleSpacesAction(a,el,workspaceContext())||handleChannelAction(a,el,workspaceContext())||handleConnectionAction(a,el,workspaceContext())||handleEcosystemAction(a,el,workspaceContext())||handleTeamAction(a,el,workspaceContext()))return;

if(a==='language-menu'){
  popover(el,`<div class="menu-caption">${tr('language.choose')}</div>`+[['zh-CN','中文'],['en','English']].map(([locale,label])=>`<button class="menu-item" role="menuitemradio" aria-checked="${getLocale()===locale}" data-action="set-language" data-locale="${locale}"><span lang="${locale}">${label}</span>${getLocale()===locale?`<span class="menu-check">${icon('check',14)}</span>`:''}</button>`).join(''));
  el.setAttribute('aria-expanded','true');return;
}
if(a==='set-language'){
  const channelOpen=!!document.querySelector('#channel-message-form');
  if(channelOpen)captureChannelDraft(workspaceContext());
  const connectionOpen=!!document.querySelector('#connection-form');
  if(connectionOpen)captureConnection(workspaceContext());
  const wizardOpen=!!document.querySelector('#eco-wizard-form');
  if(wizardOpen)captureEcosystemWizard(workspaceContext());
  if(!setLocale(el.dataset.locale))return;
  const scrollYBefore=window.scrollY,chatTop=$('.chat-scroll')?.scrollTop;
  closeOverlay({preserveConnection:connectionOpen,preserveChannel:channelOpen});render();
  window.scrollTo(0,scrollYBefore);setTimeout(()=>{if(chatTop!==undefined&&$('.chat-scroll'))$('.chat-scroll').scrollTop=chatTop;},0);
  if(channelOpen)rerenderChannelDraft(workspaceContext());
  else if(connectionOpen)rerenderConnection(workspaceContext());
  else if(wizardOpen)rerenderEcosystemWizard(workspaceContext());
  else document.querySelector('[data-action="language-menu"]')?.focus({preventScroll:true});
  toast(tr('language.changed'));return;
}

if(a==='close'){closeOverlay();return;}
if(a==='nav'){event.preventDefault();navigate(el.dataset.page,id);return;}
if(a==='collapse'){if(innerWidth<=680)state.mobileOpen=false;else state.collapsed=true;render();return;}
if(a==='expand'){state.collapsed=false;if(innerWidth<=680)state.mobileOpen=true;render();return;}
if(a==='global-search'){showSearch();return;}
if(a==='open-task'){navigate('task',id);return;}
if(a==='agent-detail'){navigate('detail',id);return;}
if(a==='chat-agent'){state.draft='';navigate('new',id);return;}
if(a==='create-menu'){popover(el,menuItem('create-agent',actionText('Create a Workmate'),'users')+menuItem('create-squad',actionText('Create a squad'),'layers'));return;}
if(a==='create-agent'||a==='create-squad'||a==='edit-agent'){closeOverlay();createAgent(a==='edit-agent'?id:null,a==='create-squad');return;}
if(a==='pick-avatar'){state.createAvatar=Number(el.dataset.value);document.querySelectorAll('.avatar-option').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el);});return;}
if(a==='save-agent'){const form=$('#agent-form');if(!form.reportValidity())return;const values=new FormData(form),name=values.get('name').trim();if(!name){form.elements.name.setCustomValidity(actionText('请输入伙伴名称'));form.reportValidity();form.elements.name.setCustomValidity('');return;}const changes={name,description:values.get('description').trim()||'No description yet',tag:values.get('tag'),avatar:state.createAvatar};if(form.dataset.edit)Object.assign(agentBy(form.dataset.edit),changes);else data.agents.push({id:'a'+Date.now(),...changes,tasks:0,skills:0});persist();closeOverlay();render();toast(form.dataset.edit?actionText('伙伴信息已更新'):actionText('已创建新的智能伙伴'));return;}
if(a==='hide-quick'){data.hideQuick=true;persist();render();toast(actionText('已隐藏 Quick start，可在工作空间菜单中恢复'));return;}
if(a==='restore-quick'){data.hideQuick=false;persist();navigate('home');toast(actionText('已恢复 Quick start'));return;}
if(a==='refresh-recommendations'){state.recommendation=(state.recommendation+3)%suggestions.length;render();return;}
if(a==='suggestion'||a==='fill-suggestion'){const s=suggestions[Number(el.dataset.index)];state.draft=suggestionText(Number(el.dataset.index));state.capabilities=s.label==='Slides'||s.label==='Deep Research'?[s.label]:[];if(a==='suggestion')navigate('new',s.agent);else render();$('#task-prompt')?.focus();return;}
if(a==='list-tab'){state.listTab=el.dataset.tab;state.query='';render();return;}
if(a==='filter'){popover(el,`<div class="menu-caption">${esc(actionText("Show tasks"))}</div>`+[['all',actionText('All tasks')],['unread',actionText('Unread')],['pinned',actionText('Pinned')],['done',actionText('Completed')],['archived',actionText('Archived')]].map(([value,label])=>menuItem('set-filter',label,'',`data-value="${value}"`,state.filter===value)).join(''));return;}
if(a==='set-filter'){state.filter=el.dataset.value;closeOverlay();$('#task-results').innerHTML=taskRows();document.querySelector('[data-action="filter"]')?.classList.toggle('selected',state.filter!=='all');return;}
if(a==='sidebar-settings'){popover(el,menuItem('show-unread',actionText('Unread tasks'),'bell')+menuItem('show-archived',actionText('Archived tasks'),'folder')+menuItem('global-search',actionText('Search tasks'),'search')+menuItem('restore-quick',actionText('Show Quick start'),'grid'));return;}
if(a==='show-unread'||a==='show-archived'){navigate('home');state.filter=a==='show-unread'?'unread':'archived';render();document.querySelector('.task-section')?.scrollIntoView({behavior:'smooth'});return;}
if(a==='task-menu'){const t=taskBy(id);if(!t)return;popover(el,menuItem('pin-task',t.pinned?actionText('Unpin task'):actionText('Pin task'),'star',`data-id="${id}"`)+menuItem('rename-task',actionText('Rename'),'edit',`data-id="${id}"`)+menuItem('archive-task',t.archived?actionText('Restore task'):actionText('Archive task'),'folder',`data-id="${id}"`));return;}
if(a==='pin-task'||a==='archive-task'){const t=taskBy(id);if(!t)return;if(a==='pin-task')t.pinned=!t.pinned;else t.archived=!t.archived;persist();closeOverlay();render();toast(a==='pin-task'?(t.pinned?actionText('任务已置顶'):actionText('已取消置顶')):(t.archived?actionText('任务已归档，可在筛选中恢复'):actionText('任务已恢复')));return;}
if(a==='rename-task'){const t=taskBy(id);closeOverlay();modal(actionText('Rename task'),`<form id="rename-form"><label class="form-field"><span>${esc(actionText("Task name"))}</span><input name="name" value="${esc(t.name)}" required maxlength="100"></label></form>`,button('close',actionText('Cancel'))+button('save-task-name',actionText('Save'),'','data-id="'+id+'"','btn primary'));return;}
if(a==='save-task-name'){const form=$('#rename-form');if(!form.reportValidity())return;const name=form.elements.name.value.trim();if(!name)return;taskBy(id).name=name;persist();closeOverlay();render();toast(actionText('任务名称已更新'));return;}
if(a==='select-agent'){popover(el,`<div class="menu-caption">${esc(actionText("Choose a workmate"))}</div>`+data.agents.map(agent=>`<button class="menu-item" data-action="choose-agent" data-id="${agent.id}">${avatar(agent.avatar,26)}<span>${esc(agent.name)}</span>${agent.id===state.agent?'<span class="menu-check">'+icon('check',14)+'</span>':''}</button>`).join(''));return;}
if(a==='choose-agent'){state.agent=id;closeOverlay();render();return;}
if(a==='select-project'){popover(el,menuItem('choose-project',actionText('No project'),'folder','data-id=""',!state.selectedProject)+data.projects.map(p=>menuItem('choose-project',p.name,'folder',`data-id="${p.id}"`,p.id===state.selectedProject)).join('')+'<div class="menu-separator"></div>'+menuItem('create-project',actionText('New project'),'plus'));return;}
if(a==='choose-project'){state.selectedProject=id;closeOverlay();render();return;}
if(a==='select-model'){popover(el,`<div class="menu-caption">${esc(actionText("Model · prototype options"))}</div>`+['Auto','Doubao','DeepSeek','Claude'].map(m=>menuItem('choose-model',actionText(m),'star',`data-value="${m}"`,state.model===m)).join(''));return;}
if(a==='choose-model'){state.model=el.dataset.value;closeOverlay();render();return;}
if(a==='capability'){const value=el.dataset.value;if(state.capabilities.includes(value))state.capabilities=state.capabilities.filter(c=>c!==value);else state.capabilities.push(value);render();return;}
if(a==='more-capabilities'){popover(el,['Data Visualization','Product Prototype','Office','Image'].map(m=>menuItem('choose-capability',actionText(m),'grid',`data-value="${m}"`,state.capabilities.includes(m))).join(''));return;}
if(a==='choose-capability'){const value=el.dataset.value;state.capabilities=state.capabilities.includes(value)?state.capabilities.filter(x=>x!==value):[...state.capabilities,value];closeOverlay();render();toast(actionText(state.capabilities.includes(value)?'actions.enabled':'actions.disabled',{name:actionText(value)}));return;}
if(a==='attach-menu'){popover(el,menuItem('upload-attachment',actionText('Upload a file'),'upload')+menuItem('select-library-file',actionText('Choose from Library'),'library'));return;}
if(a==='upload-attachment'){closeOverlay();const input=document.createElement('input');input.type='file';input.addEventListener('change',()=>{if(input.files[0]){state.attachment=input.files[0].name;render();toast(actionText('附件已加入演示任务，仅记录文件名称'));}});input.click();return;}
if(a==='select-library-file'){closeOverlay();modal(actionText('Choose a file'),data.library.map(f=>`<button class="search-result" data-action="attach-library-file" data-id="${f.id}">${icon('file',18)}<span>${esc(f.name)}</span>${icon('plus',16)}</button>`).join(''));return;}
if(a==='attach-library-file'){state.attachment=data.library.find(f=>f.id===id)?.name||'';closeOverlay();render();return;}
if(a==='remove-attachment'){state.attachment='';render();return;}
if(a==='voice'){modal(actionText('Voice input'),`<div class="modal-illustration">${icon('mic',36)}</div><p class="muted" style="text-align:center">${esc(actionText("语音转写交互演示"))}</p><label class="form-field"><span>${esc(actionText("Transcript"))}</span><textarea id="voice-text" placeholder="${esc(actionText("在这里输入模拟转写内容…"))}"></textarea></label><p class="prototype-note">${esc(actionText("此原型不会调用麦克风。输入文字后可插入任务。"))}</p>`,button('close',actionText('Cancel'))+button('use-transcript',actionText('Insert into task'),'','','btn primary'));return;}
if(a==='use-transcript'){const value=$('#voice-text').value.trim();if(!value){$('#voice-text').focus();return;}state.draft+=(state.draft?'\n':'')+value;closeOverlay();render();return;}
if(a==='send-task'){if(!state.draft.trim())return;if(state.page==='task'){const t=taskBy(state.task);t.replies=t.replies||[];t.replies.push({prompt:state.draft.trim()});state.draft='';state.attachment='';persist();render();}else startTask(state.draft);return;}
if(a==='start-code-task'){const input=$('#code-prompt');if(!input.value.trim()){input.focus();return;}state.selectedProject=$('#code-project').value;startTask(input.value,'code');return;}
if(a==='followup-suggestion'){state.draft=actionText('请将以上内容整理为行动清单，并补充优先级和验收标准。');render();$('#task-prompt').focus();return;}
if(a==='copy-answer'){const t=taskBy(id);try{await navigator.clipboard.writeText(`${t.name}\n\n${actionText('明确目标与范围，整理信息与优先级，形成可执行方案。')}\n\n${actionText('演示结果：此内容来自本地交互原型。')}`);toast(actionText('已复制到剪贴板'));}catch{modal(actionText('Copy answer'),`<label class="form-field"><span>${esc(actionText("选择并复制以下内容"))}</span><textarea readonly>${esc(t.name)}\n\n${esc(actionText('明确目标与范围，整理信息与优先级，形成可执行方案。'))}</textarea></label>`);}return;}
if(a==='detail-tab'){state.detailTab=el.dataset.tab;render();return;}
if(a==='agent-menu'){popover(el,menuItem('edit-agent',actionText('Edit workmate'),'edit',`data-id="${id}"`)+menuItem('chat-agent',actionText('New task'),'chat',`data-id="${id}"`));return;}
if(a==='edit-instructions'||a==='add-context'){const field=a==='edit-instructions'?'instructions':'context';const agent=agentBy(state.agent);modal(field==='instructions'?actionText('Edit instructions'):actionText('Edit work context'),`<label class="form-field"><span>${field==='instructions'?actionText('Instructions'):actionText('Work context')}</span><textarea id="agent-text" rows="9" style="min-height:240px">${esc(agent[field]||$('.instruction-box')?.textContent||'')}</textarea></label>`,button('close',actionText('Cancel'))+button('save-agent-text',actionText('Save'),'','data-field="'+field+'"','btn primary'));return;}
if(a==='save-agent-text'){agentBy(state.agent)[el.dataset.field]=$('#agent-text').value;persist();closeOverlay();render();toast(actionText('已保存'));return;}
if(a==='add-capability'){modal(actionText('Add capability'),`<label class="form-field"><span>${esc(actionText("Capability name"))}</span><input id="capability-name" placeholder="${esc(actionText("e.g. 竞品分析"))}" maxlength="40"></label><p class="prototype-note">${esc(actionText("将能力添加到当前伙伴的演示配置。"))}</p>`,button('close',actionText('Cancel'))+button('save-capability',actionText('Add'),'','','btn primary'));return;}
if(a==='save-capability'){const name=$('#capability-name').value.trim();if(!name){$('#capability-name').focus();return;}const agent=agentBy(state.agent);agent.extraSkills=[...(agent.extraSkills||[]),name];agent.skills++;persist();closeOverlay();render();toast(actionText('已添加能力'));return;}
if(a==='feishu-chat'||a==='demo-connect'){navigate('ecosystem');return;}
if(a==='create-automation'){closeOverlay();createAutomation();return;}
if(a==='save-automation'){const form=$('#automation-form');if(!form.reportValidity())return;const values=new FormData(form);if(!values.get('name').trim()||!values.get('description').trim())return;data.automations.unshift({id:'au'+Date.now(),name:values.get('name').trim(),description:values.get('description').trim(),schedule:values.get('frequency')+' at '+values.get('time'),enabled:true});persist();navigate('automations');toast(actionText('自动化演示已创建'));return;}
if(a==='toggle-automation'){const auto=data.automations.find(a=>a.id===id);auto.enabled=!auto.enabled;persist();render();toast(auto.enabled?actionText('自动化已恢复（演示）'):actionText('自动化已暂停（演示）'));return;}
if(a==='create-project'){closeOverlay();createProject();return;}
if(a==='save-project'){const form=$('#project-form');if(!form.reportValidity())return;const values=new FormData(form);if(!values.get('name').trim())return;const id='p'+Date.now();data.projects.unshift({id,name:values.get('name').trim(),description:values.get('description').trim(),tasks:0,updated:'Just now'});ensureTeamData(data);persist();navigate('project',id);toast(actionText('项目已创建'));return;}
if(a==='open-project'){navigate('project',id);return;}
if(a==='project-new-task'){state.selectedProject=id;state.draft='';navigate('new');return;}
if(a==='library-filter'){state.libraryFilter=el.dataset.filter;render();return;}
if(a==='hub-filter'){state.hubFilter=el.dataset.filter;render();return;}
if(a==='open-file'){showFile(id);return;}
if(a==='download-file'){downloadFile(id);return;}
if(a==='notifications'){notifications();return;}
if(a==='proactive'){modal(actionText('Proactive help'),`<div class="row" style="margin-bottom:18px">${icon('moon',24)}<div><strong>${esc(actionText("A little help, at the right time."))}</strong><p class="muted" style="font-size:12px;margin:4px 0">${esc(actionText("让智能伙伴主动关注你的工作。"))}</p></div></div><div class="proactive-row"><div class="grow">${esc(actionText("Proactive suggestions"))}<p>${esc(actionText("在工作台中展示个性化任务建议。"))}</p></div><button class="toggle ${data.proactive?'enabled':''}" role="switch" aria-checked="${!!data.proactive}" aria-label="${esc(actionText("Enable proactive suggestions"))}" data-action="toggle-proactive"></button></div><p class="prototype-note">${esc(actionText("此设置只影响原型中的演示状态。"))}</p>`,button('close',actionText('Done'),'','','btn primary'));return;}
if(a==='toggle-proactive'){data.proactive=!data.proactive;persist();el.classList.toggle('enabled',data.proactive);el.setAttribute('aria-checked',data.proactive);return;}
if(a==='profile'){popover(el,renderSpaceMenu(workspaceContext()));return;}
if(a==='shortcuts'){closeOverlay();modal(actionText('Keyboard shortcuts'),`<div class="proactive-row"><span class="grow">${esc(actionText("Search everything"))}</span><span class="kbd">⌘ / Ctrl K</span></div><div class="proactive-row"><span class="grow">${esc(actionText("Send task"))}</span><span class="kbd">⌘ / Ctrl Enter</span></div><div class="proactive-row"><span class="grow">${esc(actionText("Close dialog"))}</span><span class="kbd">Esc</span></div>`);return;}
if(a==='help'){closeOverlay();modal(actionText('Your work, with a little help.'),`<div class="help-steps">${[[actionText('选择一位伙伴'),actionText('从工作台选择适合你的智能伙伴，也可以创建自己的伙伴。')],[actionText('开始一个任务'),actionText('输入目标，选择项目与能力，然后点击发送。')],[actionText('让成果持续积累'),actionText('在 Library 查看交付文件，在 Automations 体验周期任务。')]].map(([title,desc],i)=>`<div class="help-step"><span class="step-number">${i+1}</span><div><strong>${title}</strong><p>${desc}</p></div></div>`).join('')}</div>`,button('nav',actionText('Start a task'),'arrow','data-page="new"','btn primary'));return;}
if(a==='about'){closeOverlay();modal(actionText('About WorkX'),`<div class="modal-illustration">${logo()}</div><p>${esc(tr('workspace.about'))}</p><p class="muted">${esc(actionText("支持智能伙伴管理、任务对话、全局搜索、项目空间、文件预览与自动化配置。"))}</p><p class="prototype-note">${esc(actionText("使用通用演示数据；全部操作保存在当前浏览器，不连接真实飞书服务或 AI 模型。此为独立设计原型。"))}</p>`);return;}
}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target){void action(target,event);return;}if(event.target.matches('[data-backdrop]'))closeOverlay();});
document.addEventListener('input',event=>{const el=event.target;if(handleChannelChange(el,workspaceContext())||handleConnectionChange(el,workspaceContext()))return;if(el.id==='code-prompt')state.codeDraft=el.value;if(el.id==='task-prompt'){state.draft=el.value;const send=document.querySelector('[data-action="send-task"]');if(send)send.disabled=!el.value.trim();}if(el.matches('[data-task-search]')){state.query=el.value;$('#task-results').innerHTML=taskRows();}if(el.id==='global-search')$('#global-results').innerHTML=searchResults(el.value);if(el.matches('[data-secondary-search]')){state.secondaryQuery=el.value;const pos=el.selectionStart;render();const input=$('[data-secondary-search]');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{if(handleSpacesChange(event.target))return;if(event.target.matches?.('[data-space-locale]')){void action({dataset:{action:'set-language',locale:event.target.value}},event);return;}if(handleChannelChange(event.target,workspaceContext())||handleConnectionChange(event.target,workspaceContext()))return;if(event.target.id==='code-project')state.codeProject=event.target.value;});
document.addEventListener('submit',event=>event.preventDefault());
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();return;}if(event.key==='Escape'){closeOverlay();if(state.mobileOpen){state.mobileOpen=false;render();}return;}if((event.metaKey||event.ctrlKey)&&event.key==='Enter'&&$('#task-prompt')){event.preventDefault();document.querySelector('[data-action="send-task"]')?.click();return;}if((event.key==='Enter'||event.key===' ')&&event.target.matches('.agent-card')){event.preventDefault();navigate('detail',event.target.dataset.id);return;}const menu=$('.popover');if(menu&&['ArrowDown','ArrowUp','Home','End','Tab'].includes(event.key)){event.preventDefault();const items=[...menu.querySelectorAll('button')];const index=items.indexOf(document.activeElement);const next=event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowUp'||event.key==='Tab'&&event.shiftKey?-1:1)+items.length)%items.length;items[next]?.focus();return;}const dialog=$('[role="dialog"]');if(event.key==='Tab'&&dialog){const focusables=[...dialog.querySelectorAll('button:not([disabled]),input,textarea,select,a[href]')].filter(e=>e.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.matchMedia('(max-width:680px)').addEventListener('change',()=>render());
window.addEventListener('popstate',()=>{closeOverlay();readRoute();});
// Ordinary local tasks finish on refresh; channel tasks recover as interrupted until explicitly retried.
for(const space of spaces.spaces)for(const task of space.data.tasks){if(task.status==='running'&&task.kind!=='channel')task.status='done';const seed=initialData.tasks.find(t=>t.id===task.id);if(space.id==='wx-demo'&&seed&&!task.project)task.project=seed.project;}
readRoute();
